def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c

    # early cooperation
    if n < 4:
        return 'C'

    window = min(12, n)
    recent = opp[-window:]
    recent_c = sum(1 for x in recent if x == 'C')
    recent_rate = recent_c / float(window)

    # count consecutive trailing opponent defections
    streak = 0
    for x in reversed(opp):
        if x == 'D':
            streak += 1
        else:
            break

    # count consecutive trailing opponent cooperations
    cstreak = 0
    for x in reversed(opp):
        if x == 'C':
            cstreak += 1
        else:
            break

    # Always-defector detection
    if n >= 6 and opp_d >= n - 1:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Hard-defector detection
    if n >= 10 and opp_d >= int(0.8 * n):
        if rng.random() < 0.10:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_opp == 'D':
        # long defection streak: try occasional reset, but mostly punish
        if streak >= 3:
            if cstreak == 0 and rng.random() < 0.10:
                return 'C'
            return 'D'
        # short streak: retaliate, small forgiveness chance
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we were the one defecting and they still cooperated, don't punish them.
    # Generally cooperate back.

    # Strongly cooperative opponent -> cooperate but exploit near end.
    if n >= 95:
        # endgame exploitation only against very cooperative opponents
        if opp_c >= int(0.75 * n):
            if n >= 98:
                return 'D'
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        # otherwise keep cooperating to preserve mutual gains
        return last_opp

    if n >= 90:
        if opp_c >= int(0.75 * n):
            if rng.random() < 0.30:
                return 'D'
            return 'C'
        return last_opp

    # Highly cooperative opponent: stable cooperation with rare light probe.
    if n >= 12 and opp_c >= int(0.90 * n):
        if my_d == 0 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Good cooperative rate
    if recent_rate >= 0.85:
        return 'C'

    if recent_rate >= 0.65:
        # if we defected last and they cooperated anyway, cooperate to restore
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    if recent_rate >= 0.45:
        # mixed: reciprocate last with mild forgiveness
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # opponent is mostly defecting recently
    if recent_rate >= 0.20:
        if rng.random() < 0.20:
            return 'C'
        return 'D'

    # opponent heavily defecting recently
    if rng.random() < 0.07:
        return 'C'
    return 'D'
